"""Actual original producers/approved admission; generated bytes, no optimizer."""
import base64
import hashlib
import json
from pathlib import Path

from transfer06_cohort_helpers import geometry_source_cohort
from explorer import lab_skill_workflow as flow
from explorer_shared.source_geometry_context import SO101GeometryContext
from test_transfer_mapping04 import ROOT


def test_original_calibration_artifact_survives_capture_import_approval_and_aggregate_without_raw_rewrite(tmp_path,monkeypatch):
    store,chosen,sources,originals=geometry_source_cohort(tmp_path,monkeypatch)
    aggregate=flow.build_aggregate(store,chosen['spec']['skill_id'],1)
    manifest=json.loads(Path(aggregate['aggregate_manifest']).read_bytes())
    metadata=manifest['source_calibration_metadata']['calibration_metadata']['follower'];envelope=metadata['calibration_artifact']
    raw=base64.b64decode(envelope['raw_base64'],validate=True)
    assert hashlib.sha256(raw).hexdigest()==metadata['calibration_sha256']==envelope['sha256']
    context=SO101GeometryContext(ROOT,raw,expected_sha256=envelope['sha256'],source_role='follower')
    assert context.status()['all_computable_A_resolved'] and not context.status()['physical_unit_axis_registration_inferred']
    assert aggregate['source_kind']=='SIMULATION' and len(aggregate['source_capture_bindings'])==5
    for _,path,source,binding,review in sources:
        assert hashlib.sha256(path.read_bytes()).hexdigest()==originals['original_source_manifest_sha256'][str(path)]
        assert source['calibration_metadata']['follower']['calibration_artifact']==envelope
    assert not aggregate['physical_success_inferred'] and chosen['spec']['recognized_type']=='pick_object_to_container'
